<div class="admin-page-heading"><div><span class="admin-eyebrow">TEAM ACCESS & SECURITY</span><p><?= $administrator ? 'Update this administrator account and its access level.' : 'Create a secure account for a trusted team member.' ?></p></div><a class="admin-cancel" href="<?= e(url('/admin/administrators')) ?>">← Back to administrators</a></div>
<section class="admin-panel form-panel admin-user-form-panel">
  <form method="post" action="<?= e(url('/admin/administrators/save')) ?>" class="admin-form-grid"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($administrator['id']??'') ?>">
    <div class="span-2 form-section-label"><span class="form-section-icon">♙</span><div><strong>Account information</strong><small>Basic identity details used to sign in and identify this team member.</small></div></div>
    <label>Full name<input name="name" required maxlength="120" value="<?= e($administrator['name']??'') ?>" placeholder="e.g. Ama Mensah"></label>
    <label>Work email address<input type="email" name="email" required maxlength="190" value="<?= e($administrator['email']??'') ?>" placeholder="name@company.com"></label>
    <div class="span-2 form-section-label form-section-spaced"><span class="form-section-icon">◈</span><div><strong>Access and security</strong><small>Choose what this person is allowed to manage.</small></div></div>
