    <label><?= $administrator ? 'Reset password (optional)' : 'Temporary password' ?><input type="password" name="password" <?= $administrator?'':'required' ?> minlength="12" autocomplete="new-password" placeholder="At least 12 characters"><small><?= $administrator?'Leave blank to keep the current password.':'Use at least 12 characters. Share it securely and ask the user to change it.' ?></small></label>
    <div class="span-2 admin-switch-row"><label class="admin-switch"><input type="checkbox" name="is_active" value="1" <?= !isset($administrator['is_active']) || (int)$administrator['is_active']===1?'checked':'' ?>><span class="admin-switch-track"></span><span><strong>Account active</strong><small>Active administrators can sign in according to their assigned role.</small></span></label></div>
    <div class="span-2 admin-form-actions"><button class="admin-button" type="submit"><?= $administrator?'Save Changes':'Create Administrator' ?> <span>→</span></button><a class="admin-cancel" href="<?= e(url('/admin/administrators')) ?>">Cancel</a></div>
